// MADRE en español.
//
// La clave es la frase en inglés tal como está escrita en el código; el valor es lo que dice
// MADRE. No es una traducción literal: es la misma voz en español neutro. Desde el 2026-10-10
// las funciones tienen nombres claros en los dos idiomas (Diagnóstico, Mapa de memoria,
// Coordinador, los modos Incógnito · Solo conversar · Crear · Editar · Acceso total…). Lo que no
// se traduce nunca —los comandos, las rutas y los identificadores— se queda como está.
//
// Una frase que todavía no está aquí sale en inglés, entera. Eso es a propósito.

