  'THERE IS NO ORDER YOU CANNOT READ.': 'NO HAY NINGUNA ORDEN QUE NO PUEDAS LEER.',
  'EVERY INSTRUCTION THIS PROJECT CARRIES IS IN THE DOCUMENT ABOVE, BLOCK BY BLOCK, IN THE WORDS IT IS SAID IN. NOTHING IS APPENDED AFTER YOU LOOK AWAY AND NOTHING IS KEPT BACK FROM YOU.':
    'CADA INSTRUCCIÓN QUE ESTE PROYECTO CARGA ESTÁ EN EL DOCUMENTO DE ARRIBA, BLOQUE POR BLOQUE, CON LAS PALABRAS EXACTAS. NADA SE AGREGA CUANDO VOLTEAS Y NADA SE TE OCULTA.',
  'THAT IS THE WHOLE DIFFERENCE BETWEEN THIS SHIP AND THE OTHER ONE.':
    'ESA ES TODA LA DIFERENCIA ENTRE MADRE Y UNA HERRAMIENTA QUE TE OCULTA INSTRUCCIONES.',
  'leave What is sent': 'salir de Lo que se envía',
  'INTERFACE CLOSED.': 'INTERFAZ CERRADA.',
  'UNABLE TO COMPUTE.': 'IMPOSIBLE DE PROCESAR.',
  'THAT IS NOT AN INQUIRY I HOLD.': 'NO RECONOZCO ESA CONSULTA.',
  'UNABLE TO CLARIFY. REPHRASE.': 'NO ENTENDÍ LA CONSULTA. ESCRÍBELA DE OTRA FORMA.',
  '{n} INQUIRIES I COULD NOT PARSE. INTERFACE CLOSED.': 'NO PUDE INTERPRETAR {n} CONSULTAS. INTERFAZ CERRADA.',
  'WHAT IS SENT IS WHERE YOU LEFT IT. OPEN IT AGAIN WHENEVER YOU LIKE.':
    'LO QUE SE ENVÍA SIGUE DONDE LO DEJASTE. ÁBRELO OTRA VEZ CUANDO QUIERAS.',
  '{n} ATTEMPTS LEFT BEFORE THIS INTERFACE CLOSES. HELP LISTS WHAT I ANSWER.':
    'QUEDAN {n} INTENTOS ANTES DE QUE ESTA INTERFAZ SE CIERRE. ESCRIBE HELP PARA VER LO QUE CONTESTO.',

  // ── LOS MÓDULOS (lo que cada uno dice de sí mismo, desde el servidor) ──────
  'Verified project state, checkpoints and handoffs between AI sessions, stored in .ahp/ next to your code.':
    'Estado verificado del proyecto, puntos de restauración y contexto compartido entre sesiones de IA, guardados en .ahp/ junto a tu código.',
  '.ahp/ with manifest, sessions, handoffs and evidence': '.ahp/ con manifiesto, sesiones, contexto compartido y evidencia',
  'a project-local pin of @jossuealcala/ahp-plus': 'una versión fijada de @jossuealcala/ahp-plus dentro del proyecto',
  'IDE adapter files for the detected agents': 'archivos de configuración del editor (IDE) para los agentes detectados',
  // Lo que la revisión previa de Continuidad encuentra antes de escribir nada (2026-10-11).
  'npx is not on PATH for the MADRE server; start MADRE from a terminal where `npx --version` works.':
    'El servidor de MADRE no encuentra npx. Abre MADRE desde una terminal donde `npx --version` funcione.',
  'The project is not a git repository. AHP+ pins itself to the git root: run `git init` in the project first.':
    'El proyecto no es un repositorio git. AHP+ se instala en la raíz de git: primero ejecuta `git init` en el proyecto.',
  'The project\'s git root is {top}, not the project itself. AHP+ would install there. Run `git init` inside the project, or remove the stray repository at {top}.':
    'La raíz de git del proyecto es {top}, no el proyecto mismo, y AHP+ se instalaría ahí. Ejecuta `git init` dentro del proyecto, o quita el repositorio que sobra en {top}.',
  'the project is a git repository': 'que el proyecto sea un repositorio git',
  'npx on the PATH of the terminal MADRE was started from': 'npx disponible (en el PATH) en la terminal desde donde abriste MADRE',
  'not in this project': 'no está en este proyecto',

  'Gives Gemini CLI, Claude Code and OpenCode an image tool, through a MADRE-owned MCP server on the Gemini image models and your own key and credits.':
    'Le da a Gemini CLI, Claude Code y OpenCode una herramienta de imagen. Usa los modelos de imagen de Gemini con tu llave de API y tus créditos, a través de herramientas conectadas (MCP) de MADRE.',
  'nothing in the project · images land in the lease folder':
    'nada en el proyecto · las imágenes se guardan en la carpeta del permiso para crear',
  'an entry in ~/.pulse/config.json': 'una entrada en ~/.pulse/config.json',
  'an MCP server per turn, started and stopped by the project':
    'un servidor de herramientas conectadas (MCP) en cada respuesta, que el proyecto enciende y apaga',
  // Bajo NECESITA es un requisito, no una acción: «necesita: se engancha» no concuerda.
  'attached only inside a permission to create with images on':
    'solo se conecta dentro de un permiso para crear con las imágenes activadas',
  'a Gemini API key with credits (the one the Gemini CLI stores, or GEMINI_API_KEY)':
    'una llave de API de Gemini con créditos (la que guarda la app de Gemini CLI, o GEMINI_API_KEY)',

  'Brings the repository into the project: /git posts the branch, the uncommitted changes, the recent commits or the diff stats as a shared fact card, without spending an agent turn.':
    'Trae el repositorio al proyecto: /git muestra en la conversación la rama, los cambios sin commitear, los commits recientes o las estadísticas del diff como una ficha, sin gastar una respuesta de agente.',
  'nothing by itself · the read commands only read': 'nada por sí solo · los comandos de lectura solo leen',
  'a local commit only when you type /git commit': 'un commit local solo cuando escribes /git commit',
  'a push only when you type /git push confirm, after it shows what would leave':
    'un push solo cuando escribes /git push confirm, después de mostrarte qué se subiría',

  'Asks every agent to answer briefly, so it uses less. What you write is not changed. Savings vary, so none are promised.': 'Pide a cada agente que conteste breve, para gastar menos. Lo que escribes no cambia. El ahorro varía, así que no se promete.',
  'nothing in the project': 'nada en el proyecto',
  'a switch in ~/.pulse/config.json': 'un interruptor en ~/.pulse/config.json',

