  '{n} STRIKES · CONSOLE EJECTED · AGENTS EXPENDABLE': '{n} GOLPES · CONSOLA EXPULSADA · AGENTES PRESCINDIBLES',
  'Diagnostics › Temporary lock. The archive is sealed for {n} minutes and the agents have been told, in code. Access to the memory map needs the project name again.':
    'Diagnóstico › Bloqueo temporal: la memoria queda cerrada {n} minutos y ya se avisó a los agentes de forma cifrada. Para volver a entrar al mapa de memoria, escribe otra vez el nombre del proyecto.',

  // ── LAS LECTURAS QUE CALCULA LA SALA ──────────────────────────────────────
  // De qué está hecho el archivo: seis señales, cada una con lo que la subiría.
  'HOW MUCH THERE IS': 'CUÁNTO HAY',
  '{pairs} of about {target} exchanges worth training on': '{pairs} de unos {target} intercambios que valen para entrenar',
  'Use the project. Nothing else fills this.': 'Usa el proyecto: es lo único que hace crecer esto.',
  'HOW MUCH OF IT GETS USED': 'CUÁNTO SE USA',
  '{recalled} of {total} memories have been reached for at least once': '{recalled} de {total} memorias se han usado al menos una vez',
  'Memories nobody has needed may be noise, or may simply not have come up yet. Ask the project about older decisions and see which ones answer.':
    'Las memorias que nadie ha necesitado pueden ser ruido, o simplemente no haber salido todavía. Pregúntale al proyecto por decisiones viejas y mira cuáles contestan.',
  'HOW CONNECTED IT IS': 'QUÉ TAN CONECTADO ESTÁ',
  '{connected} of {total} memories share a subject with another': '{connected} de {total} memorias comparten tema con otra',
  'An archive of unrelated notes is a list. Depth comes from returning to the same subjects.':
    'Una memoria de notas sueltas es solo una lista. La profundidad viene de volver a los mismos temas.',
  'HOW MUCH OF IT YOU JUDGED': 'CUÁNTO HAS CALIFICADO',
  '{rated} of {pairs} replies rated': '{rated} de {pairs} respuestas calificadas',
  'Rate replies with the thumbs on a bubble. A corpus nobody judged teaches what the agents said, not what you approved.':
    'Califica las respuestas con los pulgares de cada burbuja. Sin calificaciones, el modelo aprende lo que dijeron los agentes, no lo que tú aprobaste.',
  'HOW MUCH OF IT IS REAL WORK': 'CUÁNTO ES TRABAJO DE VERDAD',
  '{share}% of the corpus is recall questions, {turns} exchanges are real work':
    '{share}% de los datos de entrenamiento son preguntas de recuerdo automático; {turns} intercambios son trabajo de verdad',
  'Recall pairs are made from notes and cost nothing, so they pile up. Work in the project to balance them.':
    'Los ejemplos de recuerdo automático salen de las notas y no cuestan nada, así que se acumulan. Trabaja en el proyecto para equilibrarlos.',
  'HOW CURRENT IT IS': 'QUÉ TAN AL DÍA ESTÁ',
  '{pending} exchanges nobody has distilled yet, of {entries}': '{pending} intercambios todavía sin resumir en notas, de {entries}',
  'The archivist catches up on its own. A backlog that never clears means it cannot run: check who is allowed to distil.':
    'MADRE resume en notas por su cuenta. Si la lista de pendientes nunca baja, es que no puede hacerlo: revisa quién tiene permiso para resumir.',
  'Worth training on. Export and run the recipe.': 'Ya sirve para entrenar. Exporta los datos y sigue la receta.',
  'Usable, and it will be better for waiting.': 'Ya sirve, y va a estar mejor si esperas.',
  'It has a shape. Too thin to train on.': 'Ya tiene forma, pero todavía es muy poco para entrenar.',
  'A few things remembered, little connecting them.': 'Unas cuantas cosas recordadas, poco que las conecte.',
  'Nothing has been distilled yet.': 'Todavía no se ha resumido nada en notas.',

  // El veredicto: una frase y una sola cosa que hacer.
  'THE PROJECT': 'EL PROYECTO',
  'Settle the {n} contradictions the memory reviewer found. Until they are settled, everything built on this memory inherits them.':
    'Resuelve las {n} contradicciones que encontró el revisor de memoria. Hasta que las resuelvas, todo lo que se construya sobre la memoria las hereda.',
  'Answer the {n} questions the project wrote for itself. They are the holes this test is finding.':
    'Contesta las {n} preguntas que el proyecto anotó por su cuenta. Son los huecos que encontró esta prueba.',
  'Keep working in the project. The archive fills where the work happens, and this test measures exactly that.':
    'Sigue trabajando en el proyecto. La memoria crece donde ocurre el trabajo, y eso es justo lo que mide esta prueba.',
  'Nothing contradicts anything and the archive answers what this project asks.':
    'Nada contradice nada y la memoria contesta lo que este proyecto pregunta.',
  'Run the third test: it puts real questions from this project back to the local model and says whether it lands where the agents landed.':
    'Corre la tercera prueba: le hace al modelo local preguntas reales de este proyecto y compara si llega a la misma respuesta que dieron los agentes.',
  'This project is ready to be worked on with the local model.': 'Este proyecto ya se puede trabajar con el modelo local.',
  'Nothing is wrong. {n} memories have had every chance and were never the answer: look at them and decide.':
    'No hay nada mal. {n} memorias nunca han servido como respuesta, aunque tuvieron muchas oportunidades: revísalas y decide qué hacer.',
  'Nothing to fix. Keep using the project; the archive grows where the work is.':
    'Nada que arreglar. Sigue usando el proyecto; la memoria crece donde está el trabajo.',
  'The local model does not land where the agents land yet. Keep the archive growing and run this test again in a week.':
    'El modelo local todavía no llega a las mismas respuestas que los agentes. Deja que la memoria siga creciendo y corre esta prueba otra vez en una semana.',

  // Lo que dice cada prueba al terminar.
  'No exchange in this project is long enough to test with yet.': 'Todavía no hay en este proyecto un intercambio lo bastante largo para probar con él.',
  'meaning': 'significado',
  'words': 'palabras',
  ' and against a control': ' y comparadas con un grupo de control',
  '{hits} of {n} questions this project actually asked had their answer already in the archive, matched by {method}{control}.':
    '{hits} de {n} preguntas que este proyecto hizo de verdad ya tenían su respuesta en la memoria, emparejadas por {method}{control}.',
  'The memory reviewer found {n} contradictions nobody has settled.': 'El revisor de memoria encontró {n} contradicciones que nadie ha resuelto.',
  'The memory reviewer found 1 contradiction nobody has settled.': 'El revisor de memoria encontró 1 contradicción que nadie ha resuelto.',
  'Settle the contradiction the memory reviewer found. Until it is settled, everything built on this memory inherits it.': 'Resuelve la contradicción que encontró el revisor de memoria. Mientras no se resuelva, todo lo que se construya sobre esta memoria la hereda.',
  'Nothing is open, but doubtful memories are being filed more often lately than they used to be.':
    'No hay nada abierto, pero últimamente se están archivando memorias dudosas más seguido que antes.',
  'Nothing contradicts anything: {standing} notes stand, {refuted} were taken out of circulation.':
    'Nada contradice nada: {standing} notas siguen en pie, {refuted} salieron de circulación.',
  'This test needs smart search: two answers cannot be compared by their words alone.':
    'Esta prueba necesita la búsqueda inteligente: dos respuestas no se pueden comparar solo por sus palabras.',
  'No question in this project was answered by an agent other than the local one yet.':
    'Todavía no hay preguntas de este proyecto contestadas por un agente que no sea el local.',
  'Stopped after {index} of {n}.': 'Detenida después de {index} de {n}.',
  ', and not merely in the same project': ', y no solo dentro del mismo proyecto',
  'On {matched} of {n} real questions the local model landed where the agent of the day landed{control}.':
    'En {matched} de {n} preguntas reales el modelo local llegó a la misma respuesta que el agente de aquel día{control}.',

