  'created · {n} {files}': 'creados · {n} {files}',
  'file': 'archivo',
  'files': 'archivos',
  // La severidad de una condición de MU/TH/UR. En mayúsculas porque así se lee la ficha, y
  // porque así no choca con 'warning' en minúsculas, que es el nivel de una cuota.
  'BLOCKING': 'BLOQUEANTE',
  'COMMON': 'COMÚN',
  'DEGRADED': 'LIMITADO',
  'ALREADY FIXED': 'RESUELTO',
  'INFORMATIONAL': 'INFORMATIVO',
  'TRANSIENT': 'PASAJERO',
  'TUNABLE': 'AJUSTABLE',
  'WARNING': 'AVISO',
  'a note its own sources do not support': 'una nota que sus propias fuentes no respaldan',

  // ── DOS CONDICIONES QUE REPORTÓ QUIEN LA USA ──────────────────────────────
  'ANTHROPIC_API_KEY takes precedence over the claude.ai plan':
    'ANTHROPIC_API_KEY tiene prioridad sobre tu plan de claude.ai',
  'Claude Code found an API key as well as the claude.ai login, and the key wins. It may come from your shell profile — MADRE hands the CLI the environment exactly as this machine has it — or from the `env` block of ~/.claude/settings.json, which is where a key pasted into Settings › Agents is written. The turn is billed to the API account, not to the plan, and your organisation connectors do not load.':
    'Claude Code encontró una llave de API además del inicio de sesión de claude.ai, y usa la llave. Puede venir del perfil de tu shell —MADRE le pasa a la app el entorno tal como lo tiene esta computadora— o del bloque `env` de ~/.claude/settings.json, que es donde se guarda una llave pegada en Ajustes › Agentes. Cada respuesta se cobra a la cuenta de API, no al plan, y los conectores de tu organización no cargan.',
  'Decide which one you mean. To work on the API, this message is only a notice and can be ignored. To work on the plan, take the key out of wherever it is set: your shell profile, or the `env` block of ~/.claude/settings.json if you pasted it into MADRE — then open the project again.':
    'Decide cuál quieres. Para trabajar con la API, este mensaje es solo un aviso y se puede ignorar. Para trabajar con el plan, quita la llave de donde esté puesta: el perfil de tu shell, o el bloque `env` de ~/.claude/settings.json si la pegaste en MADRE; luego vuelve a abrir el proyecto.',
  'The agent is pointed at a custom endpoint': 'El agente se conecta a una dirección no oficial',
  'The installed CLI inherited a base-URL override from this computer, so its request was going to another gateway instead of the official agent service. A demand to join a Telegram channel comes from that gateway, not from MADRE, Anthropic or OpenAI. MADRE now names that route and stops before sending the briefing.':
    'La app de este agente heredó de esta computadora una dirección distinta a la oficial, así que sus peticiones iban a un servicio intermediario y no al servicio oficial del agente. La exigencia de unirse a un canal de Telegram viene de ese intermediario, no de MADRE, Anthropic ni OpenAI. MADRE ahora muestra esa dirección y se detiene antes de enviarle nada al agente.',
  'Do not subscribe or enter credentials. Remove the base-URL override and reopen MADRE to use the official service. If the gateway is intentional and you have verified who operates it, explicitly allow only that agent.':
    'No te suscribas ni escribas credenciales. Quita la dirección modificada y vuelve a abrir MADRE para usar el servicio oficial. Si el intermediario es intencional y verificaste quién lo opera, autoriza explícitamente solo a ese agente.',
  // La condición que declara el módulo PLAYWRIGHT. Las de los módulos viven en su archivo, no
  // en troubleshooting.js, y por eso se quedaron fuera del catálogo hasta ahora.
  'TEST BROWSER: the browser server is not installed': 'NAVEGADOR DE PRUEBAS: el servidor de navegador no está instalado',
  'The TEST BROWSER module runs @playwright/mcp per turn. Two different things have to be on this computer and only one of them is the package: the server, and the browser build that this version of it expects. A server that starts without its browser answers every tool call with "Browser … is not installed", and one that cannot start at all reaches the agent as CONNECTION_CLOSED.':
    'El módulo NAVEGADOR DE PRUEBAS usa @playwright/mcp en cada respuesta. Necesita dos cosas distintas en esta computadora, y solo una es el paquete: el servidor y la versión del navegador que ese servidor espera. Si el servidor arranca sin su navegador, cada herramienta responde «Browser … is not installed»; si no logra arrancar, al agente le llega CONNECTION_CLOSED.',
  'Install the server once, globally, then its browser — the browser is downloaded by the server itself, not by the playwright CLI — and RECHECK in MODULES.':
    'Instala el servidor una vez, de forma global, y después su navegador —lo descarga el propio servidor, no la herramienta de playwright— y dale RE-REVISAR en MÓDULOS.',
  // El registro de errores: un código que se dicta por teléfono, y una salida por fila.
  // Lo que un agente puede hacer, dicho dentro de una frase: infinitivo, no el imperativo de
  // la etiqueta suelta de su ficha. «puede crea» era el botón metido en una oración.
  'read the project': 'leer el proyecto',
  'receive images': 'recibir imágenes',
  'generate images': 'generar imágenes',
  'reach the web': 'consultar la web',
  'the project · local': 'el proyecto · local',
  '@{agent} may {what}': '@{agent} puede {what}',
  ' (cannot {what})': ' (no puede {what})',
  'create files': 'crear archivos',
  'review it with': 'revisarlo con',
  'no session': 'sin sesión',
  'CLICK A LINE NUMBER TO SELECT · SHIFT FOR A RANGE':
    'CLIC EN UN NÚMERO DE LÍNEA PARA SELECCIONAR · SHIFT PARA UN RANGO',
  'Last changed by @{agent} · {when}': 'Último cambio: @{agent} · {when}',
  '@{agent} changed {file} here · {when}': '@{agent} cambió {file} aquí · {when}',
  'Refresh files': 'Actualizar archivos',
  'Diagnostics › {name} declares {fields}, which this MADRE does not know. A typo, or a field from a newer version.':
    'Diagnóstico › {name} declara {fields}, que esta MADRE no conoce. Puede ser un error de escritura o un campo de una versión más nueva de MADRE.',
