  'Write the terms first.': 'Primero escribe los términos.',
  'Still showing in {events} records · {entries} exchanges · {memories} memories.': 'Aún aparecen en {events} registros · {entries} intercambios · {memories} memorias.',
  'All clean: none of these words is saved in the project.': 'Todo limpio: ninguna de estas palabras está guardada en el proyecto.',
  'One per line': 'Uno por línea',
  'What the project shows in their place.': 'Lo que el proyecto muestra en su lugar.',
  'The terms stay in config.json; the project only records how many. PULSE_PRIVATE_TERMS is set, so its terms are added on every launch.': 'Los términos se quedan en config.json; el proyecto solo registra cuántos. PULSE_PRIVATE_TERMS está definida, así que sus términos se suman en cada arranque.',
  'The list stays on this computer; the project only notes how many words it has.': 'La lista se queda en esta computadora; el proyecto solo anota cuántas palabras tiene.',
  'Hidden automatically': 'Se ocultan solos',
