  'Where they open': 'Dónde se abren',
  'Each one remembers how you left it. This is the same choice, without opening them.': 'Cada uno recuerda cómo lo dejaste. Aquí puedes elegirlo sin abrirlos.',
  "The project's files, beside the conversation or as a window of their own.": 'Los archivos del proyecto, al lado de la conversación o en su propia ventana.',
  'Beside': 'Al lado',
  'Window': 'Ventana',
  'Your servers': 'Tus servidores',
  'Web pages your project runs on this computer: beside the conversation, or floating.': 'Las páginas web que tu proyecto corre en esta computadora: junto a la conversación o flotando.',
  'Docked': 'Acoplado',
  'It always opens beside the conversation: opening a file never splits the project on its own. From there it can float as a window.': 'Siempre se abre al lado de la conversación: abrir un archivo nunca divide la pantalla por sí solo. Desde ahí puedes sacarlo a una ventana.',
  'What they can show': 'Lo que pueden mostrar',
  'These switches are the same ones as in MODULES.': 'Estos interruptores son los mismos que en MÓDULOS.',
  'Web pages, images and documents show as they look, safely. Off, you see their code.': 'Páginas web, imágenes y documentos se ven tal como son, de forma segura. Apagada, ves su código.',
  'Test browser': 'Navegador de pruebas',
  'Agents can open and check your project\'s pages, without reaching anything else.': 'Los agentes pueden abrir y revisar las páginas de tu proyecto, sin llegar a nada más.',
  'Settings for files and servers': 'Ajustes de archivos y servidores',
  'Always': 'Siempre',
  'Turned on': 'Encendido',
  'Turned off': 'Apagado',
