  'Yours': 'Tuyos',
  'Back to modules': 'Volver a Módulos',
  'Open as a window': 'Abrir en ventana',
  '{n} of your modules did not load · see why': '{n} de tus módulos no cargaron · ver por qué',
  'Create your module': 'Crea tu módulo',
  'One file. Your agent can write it for you.': 'Un archivo. Tu agente puede escribirlo por ti.',
  'A module is one file: no build, no dependencies, nothing to register. It can be a switch, a few settings, a slash command, a tool for the agents, a card of its own, or an integration with a service you already use.': 'Un módulo es un archivo: sin compilar, sin dependencias, sin registrarlo en ningún lado. Puede ser un interruptor, unos ajustes, un comando con /, una herramienta para los agentes, una tarjeta propia o una integración con un servicio que ya usas.',
  'Ask for one in the project': 'Pedirlo en el proyecto',
  'Ask for it': 'Pídelo',
  'Type /module and say what it should do. The agent reads the SDK and writes the file; you review it and decide whether it is installed.': 'Escribe /module y di qué debe hacer. El agente lee la guía para crear módulos (SDK) y escribe el archivo; tú lo revisas y decides si se instala.',
  'every project': 'todos los proyectos',
  'Read the SDK ↗': 'Leer la guía de módulos (SDK) ↗',
  'Or write it yourself': 'O escríbelo tú',
  'Put the file in one of these folders. A file somebody else wrote goes in with + Add a module, and MADRE checks it before it runs.': 'Pon el archivo en una de estas carpetas. Un archivo que escribió alguien más se agrega con + Agregar un módulo, y MADRE lo revisa antes de que corra.',
  'Reload modules': 'Recargar módulos',
  'Load it': 'Cárgalo',
  'Press Reload modules and it appears on the board with its own card, no restart.': 'Presiona Recargar módulos y aparece en el tablero con su propia tarjeta, sin reiniciar.',
  'If it talks to a service': 'Si habla con un servicio',
  'Connecting to a service from outside is almost always possible, if that service lets you get your own key in minutes and revoke it. Your module declares the key it needs, where it reaches and which of its tools send; MADRE draws the field, answers for the traffic and holds sending until #4 FULL ACCESS.': 'Casi siempre puedes conectar un servicio externo, si te deja crear tu propia llave de API en minutos y revocarla. Tu módulo dice qué llave de API necesita, a dónde se envía y qué herramientas mandan datos. MADRE muestra el campo para la llave, se encarga de las conexiones y bloquea los envíos hasta que actives #4 ACCESO TOTAL.',
  'Did not load': 'No se cargaron',
  'Compact replies from every agent': 'Respuestas compactas de cada agente',
  'How hard each agent should think': 'Cuánto debe pensar cada agente',
