  'Install {version}': 'Instalar {version}',
  'What this module lets you set. Each change is saved as you make it.': 'Lo que este módulo te deja ajustar. Cada cambio se guarda al hacerlo.',
  'Keys': 'Llaves de API',
  'Spending': 'Consumo',
  'What your use taught': 'Lo que aprendió de tu uso',
  'Per agent and per kind of request: the lowest effort that was enough in your own turns, learned for no tokens. Below, a test that learns faster, for a price.':
    'Por agente y por tipo de pedido: el esfuerzo más bajo que fue suficiente en tus propias respuestas, aprendido sin gastar tokens. Abajo, una prueba que aprende más rápido, pero tiene costo.',
  'When a lower level might be enough, MADRE offers to try it on a single message and watches how it goes; if it falls short, the next one goes back up.':
    'Cuando un nivel de esfuerzo más bajo podría bastar, MADRE te propone probarlo en un solo mensaje y revisa el resultado; si no es suficiente, el siguiente mensaje vuelve a subir.',
  'What this project was charged, what it was not, and what the Token saver does to an answer. Measured here, never promised.': 'Lo que se le cobró a este proyecto, lo que no, y lo que el Ahorro de tokens le hace a una respuesta. Medido aquí, nunca prometido.',
  'Get a newer file': 'Traer un archivo más nuevo',
  'Newer file': 'Archivo más nuevo',
  'It stops loading. The file stays where it is.': 'Deja de cargarse. El archivo se queda donde está.',
  'Ollama on this computer: no provider tokens, nothing leaves.': 'Ollama corre en esta computadora: no gasta tokens de tu proveedor y nada sale de tu equipo.',
