  'Settings it needs, like an API key. Secret ones stay locked in MADRE, never in a file.': 'Lo que necesita, como una llave de API. Las secretas se guardan bajo llave en MADRE, nunca en un archivo.',
  'The MCP address the service gives you, starting with https://.': 'La dirección MCP que te da el servicio, empezando con https://.',
