  'The project that reads can hand it notes. They wait there until you accept them (or an agent of that project in #3 EDIT or above): nothing enters its memory on its own.': 'El proyecto que lee puede entregarle notas. Esperan allí hasta que las aceptes (o un agente de ese proyecto en #3 EDITAR o más): nada entra a su memoria por sí solo.',
